import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1/"
HDR = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}}


def api_tool(name, desc, body_props, required, pre="", post="", retries=0, mapping=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": BASE + name},
                    "method": {"type": "string", "default": "POST"},
                    "headers": HDR,
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


def ok_cond(var):
    return {"logic": "or", "conditions": [
        {"variable": var, "operator": "equals", "operand": "true"},
        {"variable": var, "operator": "equals", "operand": "True"}]}


CLOSE_T = {"target_node": "hang_up", "description": "The call was closed", "condition": ok_cond("close_call_response.data.ok")}

TURN_RULES = ("After every tool result, speak to the customer or call the next tool. Never end a turn with nothing. "
              "Call one tool per message. When a tool result has what_to_do_next, do exactly what it says. "
              "Before calling close_call, thank the customer and say goodbye in the same message.\n\n")

# ---------------------------------------------------------------- hooks
COMMON_POST_HEAD = (
    "try:\n"
    "    if isinstance(result, dict):\n"
    "        result.pop('header', None)\n"
    "        d = result.get('data')\n"
    "        if not isinstance(d, dict):\n"
    "            d = dict()\n"
    "            result['data'] = d\n"
)

# --- close_call
CLOSE_PRE = r'''
try:
    b = config.get('body')
    if isinstance(b, dict):
        tr = str(vars.get('transferred_queue') or '')
        promised = [p for p in str(vars.get('promised_ids') or '').split(',') if p]
        out = str(b.get('outcome') or '')
        if tr:
            b['outcome'] = 'transferred'
            b['reason'] = 'human' if tr == 'general' else tr
        elif promised and out in ('no_promise', 'paid', 'promise'):
            b['outcome'] = 'promise'
        elif out in ('no_promise', 'paid') and vars.get('pid_order'):
            order = [p for p in str(vars.get('pid_order')).split(',') if p]
            notes = [str(vars.get('note_' + p) or '') for p in order]
            got = [n for n in notes if n]
            if got and len(got) == len(order):
                if all(n == 'paid' for n in got):
                    b['outcome'] = 'paid'
                else:
                    b['outcome'] = 'no_promise'
                    b['reason'] = [n for n in got if n != 'paid'][0]
        if b.get('outcome') in ('promise', 'paid'):
            b.pop('reason', None)
except Exception:
    pass
'''
CLOSE_POST = COMMON_POST_HEAD + r'''
        if d.get('ok') is True:
            d['what_to_do_next'] = 'The call is closed. Say nothing more.'
        else:
            d['what_to_do_next'] = 'close_call did not go through. Call close_call again with the same outcome and reason.'
except Exception:
    pass
'''

CLOSE_DESC = ("End the call with its outcome. CALL it exactly once, as the very last tool call, after you said goodbye. "
              "Outcomes and reasons: promise (no reason) = at least one promise recorded; paid (no reason) = customer already paid; "
              "transferred + restructuring | human | support; no_promise + refused | hardship | dispute | service_error; "
              "not_verified + failed | declined; not_reached + callback | no_callback | wrong_number | deceased | unclear.")


def close_tool():
    return api_tool("close_call", CLOSE_DESC, {
        "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"],
                    "description": "One of: promise, paid, transferred, no_promise, not_verified, not_reached.",
                    "default": "{{outcome}}"},
        "reason": {"type": "string",
                   "enum": ["restructuring", "human", "support", "refused", "hardship", "dispute", "service_error",
                            "failed", "declined", "callback", "no_callback", "wrong_number", "deceased", "unclear"],
                   "description": "Reason that belongs to the outcome (see tool description). Leave empty for promise and paid.",
                   "default": "{{reason}}"},
    }, ["outcome"], CLOSE_PRE, CLOSE_POST)


# --- transfer
TRANSFER_POST = COMMON_POST_HEAD + r'''
        if d.get('ok') is True:
            q = ''
            try:
                q = str(vars.get('transfer_to_agent_args.queue') or '')
            except Exception:
                q = ''
            if q:
                vars['transferred_queue'] = q
            r = 'human' if q == 'general' else (q or 'the queue reason: restructuring, support, or human for general')
            d['what_to_do_next'] = ('The transfer worked. Tell the customer a colleague will take over, thank them, say goodbye, '
                                    'then call close_call with outcome transferred and reason ' + r + '. Do NOT call add_note.')
        else:
            d['what_to_do_next'] = 'The transfer failed. Tell the customer you could not connect them right now. Call transfer_to_agent once more.'
except Exception:
    pass
'''


def transfer_tool(desc_extra):
    return api_tool("transfer_to_agent",
                    "Hand the call to a person. CALL it only when: " + desc_extra,
                    {"queue": {"type": "string", "enum": ["restructuring", "general", "support"],
                               "description": "restructuring = customer asks for a new payment plan or lower instalments; "
                                              "general = customer insists on a human; support = hardship (illness, death in the family, job loss) and the customer accepted the support team.",
                               "default": "{{queue}}"}},
                    ["queue"], "", TRANSFER_POST)


# --- schedule_callback
CB_PRE = r'''
import re, datetime
try:
    b = config.get('body')
    vars['cb_block'] = ''
    if isinstance(b, dict):
        t = str(b.get('time') or '').strip().lower().replace('.', ':')
        m = re.match(r'^(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?$', t)
        hh = mm = None
        if m:
            hh = int(m.group(1)); mm = int(m.group(2) or 0)
            ap = (m.group(3) or '').replace('.', '')
            if ap == 'pm' and hh < 12:
                hh += 12
            if ap == 'am' and hh == 12:
                hh = 0
            b['time'] = '%02d:%02d' % (hh, mm)
        ds = str(b.get('date') or '')[:10]
        ok_days = [str(vars.get('today_iso') or ''), str(vars.get('next_bd_iso') or '')]
