def isbd(x):
    return x.weekday() < 5 and x.isoformat() not in HOL
def nth_bd(x, n):
    c = 0
    while c < n:
        x = x + datetime.timedelta(days=1)
        if isbd(x):
            c += 1
    return x
def nextbd(x):
    while not isbd(x):
        x = x + datetime.timedelta(days=1)
    return x
def fd(x):
    return WD[x.weekday()] + ' ' + str(x.day) + ' ' + x.strftime('%B') + ' ' + str(x.year) + ' (' + x.isoformat() + ')'
def money(v):
    try:
        v = float(v)
    except Exception:
        return str(v)
    if abs(v - round(v)) < 0.005:
        return str(int(round(v)))
    return '%.2f' % v
def parse_list(v):
    if isinstance(v, list):
        return v
    if isinstance(v, str) and v.strip():
        try:
            return json.loads(v)
        except Exception:
            pass
        try:
            import ast
            return ast.literal_eval(v)
        except Exception:
            pass
    return None
try:
    now = str(vars.get('now') or '')
    try:
        today = datetime.date.fromisoformat(now[:10])
    except Exception:
        today = datetime.date(2026, 10, 14)
    prods = None
