            if m:
                i = int(m.group(1))
                if i not in flat:
                    flat[i] = dict()
                flat[i][m.group(2)] = vars.get(k)
        prods = [flat[i] for i in sorted(flat.keys())]
    prods = [p for p in (prods or []) if isinstance(p, dict) and p.get('product_id')]
    if not prods:
        raise ValueError('no products')
    monday = today - datetime.timedelta(days=today.weekday())
    def last_bd_of_week(mon):
        for off in (4, 3, 2, 1, 0):
            x = mon + datetime.timedelta(days=off)
            if isbd(x):
                return x
        return None
    a1 = last_bd_of_week(monday)
    if a1 is None or a1 <= today:
        a1 = last_bd_of_week(monday + datetime.timedelta(days=7))
    pp = []
    facts = []
    states = []
    for i, p in enumerate(prods):
        t = str(p.get('type') or '')
