            floor = p.get('minimum_payment')
            fname = 'minimum payment'
        elif t == 'car_loan':
            label = 'car loan'
            floor = p.get('instalment_amount')
            fname = 'instalment amount'
        else:
            label = 'personal loan'
            floor = p.get('instalment_amount')
            fname = 'instalment amount'
        dl_ = int(float(p.get('days_late') or 0))
        due = float(p.get('past_due') or 0)
        try:
            fl = float(floor)
        except Exception:
            fl = due
        if dl_ <= 7:
            band = 'early'; dlb = nth_bd(today, 12); att = 1
        else:
            band = 'late'; dlb = nth_bd(today, 7); att = 2
        a1p = a1 if a1 <= dlb else dlb
        pp.append(dict(id=str(p.get('product_id')), label=label, past_due=due, past_due_s=money(due), floor=fl, floor_s=money(fl), deadline=dlb.isoformat(), deadline_s=fd(dlb)))
        states.append('Your ' + label + ' has ' + money(due) + ' past due, ' + str(dl_) + ' days late.')
        s = ('PRODUCT ' + str(i + 1) + ': ' + label + ' | product_id ' + str(p.get('product_id')) +
