        a1p = a1 if a1 <= dlb else dlb
        pp.append(dict(id=str(p.get('product_id')), label=label, past_due=due, past_due_s=money(due), floor=fl, floor_s=money(fl), deadline=dlb.isoformat(), deadline_s=fd(dlb)))
        states.append('Your ' + label + ' has ' + money(due) + ' past due, ' + str(dl_) + ' days late.')
